    const MONO     = "var(--font-overpass-mono), 'Overpass Mono', Menlo, monospace";
    const CREAM    = "#FFF8F1";
    const SAND     = "#E0BE9A";
    const INK      = "#1F1F1F";
    const MUTED    = "#5B4D43";
    const resolvedHref = tenantSlug && breadcrumbHref.startsWith("/")
