                color: CREAM,
                border: `1px solid ${CREAM}`,
                fontFamily: SANS,
                fontSize: "0.82rem",
                fontWeight: 600,
                letterSpacing: "0.24em",
                textTransform: "uppercase",
                textDecoration: "none",
